1	package indexroom
2	
3	import (
4		"errors"
5		"io"
6		"reflect"
7		"strconv"
8		"strings"
9		"testing"
10	)
11	
12	// v1Chain wraps block JSON fragments into a version-1 snapshot.
13	func v1Chain(blocks ...string) string {
14		return `{"version":1,"tip":` + strconv.Itoa(len(blocks)) + `,"blocks":[` +
15			strings.Join(blocks, ",") + `]}`
16	}
17	
18	// v2Chain wraps block JSON fragments into a version-2 snapshot; each
19	// fragment must carry its own timestamp field.
20	func v2Chain(blocks ...string) string {
21		return `{"version":2,"tip":` + strconv.Itoa(len(blocks)) + `,"blocks":[` +
22			strings.Join(blocks, ",") + `]}`
23	}
24	
25	func TestRestoreRejectsInvalidStringEncoding(t *testing.T) {
26		// badByte is an invalid UTF-8 byte inside an otherwise valid string.
27		badByte := "\xff"
28		cases := map[string]struct {
29			input string
30			want  []string // substrings the error must carry
31		}{
32			"invalid utf8 in hash": {
33				v1Chain(`{"height":1,"hash":"h` + badByte + `1","parent":"g","txs":[]}`),
34				[]string{`"hash"`, "height 1"},
35			},
36			"invalid utf8 in parent": {
37				v1Chain(`{"height":1,"hash":"h1","parent":"g` + badByte + `","txs":[]}`),
38				[]string{`"parent"`, "height 1"},
39			},
40			"invalid utf8 in tx id": {
41				v1Chain(`{"height":1,"hash":"h1","parent":"g","txs":["ok","t` + badByte + `"]}`),
42				[]string{`"txs"`, "height 1", "element 1"},
43			},
44			"invalid utf8 in last block": {
45				v1Chain(
46					`{"height":1,"hash":"h1","parent":"g","txs":[]}`,
47					`{"height":2,"hash":"h`+badByte+`2","parent":"h1","txs":[]}`,
48				),
49				[]string{`"hash"`, "height 2"},
50			},
51			"invalid utf8 in v2 block": {
52				v2Chain(`{"height":1,"hash":"h1","parent":"g` + badByte + `","txs":[],"timestamp":5}`),
53				[]string{`"parent"`, "height 1"},
54			},
