func TestRejectedIngestionKeepsQueriesAndCursors(t *testing.T) {
	index := chain(t,
		Block{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"keep", "keep"}},
		Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"keep"}},
