func TestUnicodeIdentifiersRoundTripThroughSnapshots(t *testing.T) {
	for _, withTime := range []bool{false, true} {
		name := "version1-no-times"
		if withTime {
			name = "version2-with-times"
		}
		t.Run(name, func(t *testing.T) {
